"""Migration of the Meridian CRM case_lifecycle workflow."""

from __future__ import annotations


def _value(record: dict, field: str) -> str:
    """Return a legacy VRL field value, treating missing values as empty."""
    value = record.get(field, "")
    return "" if value is None else value


def _owner_present(record: dict) -> bool:
    return _value(record, "OWNER_UID") != ""


def _not_escalated(record: dict) -> bool:
    return _value(record, "ESC_FLG") != "Y"


def _has_resolution_date(record: dict) -> bool:
    value = _value(record, "RES_DT")
    return value != "" and value != "00000000"


def _nvl_severity(record: dict) -> str:
    value = _value(record, "SEV_CD")
    return value if value != "" else "3"


def fire(state: str, event: str, record: dict) -> dict:
    """Dispatch one explicit case_lifecycle event.

    The transition table is kept in the same order as the legacy XML.
    """
    updated = dict(record)

    # N -> A, assign
    if state == "N" and event == "assign" and _owner_present(record):
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ASSIGN"],
            "notifies": [],
            "matched": True,
        }

    # N -> A, auto_escalate
    if state == "N" and event == "auto_escalate":
        updated["ESC_FLG"] = "Y"
        updated["SEV_CD"] = _nvl_severity(updated)
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    # A -> A, auto_escalate
    if state == "A" and event == "auto_escalate" and _not_escalated(record):
        updated["ESC_FLG"] = "Y"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    # A -> P, await_customer
    if state == "A" and event == "await_customer":
        return {
            "state": "P",
            "record": updated,
            "audits": ["CASE_PEND"],
            "notifies": [],
            "matched": True,
        }

    # P -> A, customer_reply
    if state == "P" and event == "customer_reply":
        return {
            "state": "A",
            "record": updated,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    # A -> R, resolve
    if state == "A" and event == "resolve" and _has_resolution_date(record):
        return {
            "state": "R",
            "record": updated,
            "audits": ["CASE_RES"],
            "notifies": [],
            "matched": True,
        }

    # R -> X, close
    if state == "R" and event == "close":
        return {
            "state": "X",
            "record": updated,
            "audits": ["CASE_CLOSE"],
            "notifies": [],
            "matched": True,
        }

    # R -> A, reopen
    if state == "R" and event == "reopen":
        updated["RES_DT"] = "00000000"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_REOPEN"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": updated,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
